/* ===== Elysian brand theme tokens + sidebar + Home (patches-8) ===== */
html{--gold:#b8974c;--side-bg:#0F1E2E;--side-tx:rgba(255,255,255,.82);--side-active-bg:rgba(184,151,76,.18);--th-bg:#0F1E2E;--th-tx:#c9a84c;--card:var(--bg)}
html[data-theme="dark"]{
  --bg:#16181d;--bg2:#1e2127;--bg3:#0e0f12;
  --bg-ok:#13291d;--bg-err:#2a1614;--bg-warn:#2a2411;
  --tx:#e8e5de;--tx2:#b3aea2;--tx3:#8b8678;
  --tx-ok:#4ade80;--tx-err:#f87171;--tx-warn:#fbbf24;
  --bdr:rgba(255,255,255,.12);--bdr2:rgba(255,255,255,.22);
  --side-bg:#0b0d11;--th-bg:#0b0d11;--th-tx:#c9a84c;--card:#1e2127;
}
html[data-theme="dark"] body{background:var(--bg3)}
html[data-theme="dark"] .tbl th{background:var(--th-bg);color:var(--th-tx)}
html[data-theme="dark"] .tbl tr:hover td{background:var(--bg2)}
html[data-theme="dark"] .btn.primary{background:#243447;border-color:#243447;color:#fff}
html[data-theme="dark"] .btn.gold{background:var(--gold);border-color:var(--gold);color:#141414}
html[data-theme="dark"] input[type=text],html[data-theme="dark"] input[type=number],html[data-theme="dark"] input[type=date],html[data-theme="dark"] input[type=email],html[data-theme="dark"] select,html[data-theme="dark"] textarea{background:var(--bg2);color:var(--tx)}
html[data-theme="dark"] .card{background:var(--card)}
html[data-theme="dark"] .kpi{background:var(--bg2)}
/* ===== Sidebar (transform the existing #hdr into a left rail) ===== */
#hdr{flex-direction:column!important;align-items:stretch!important;gap:0!important;width:216px!important;height:100vh!important;position:fixed!important;top:0!important;left:0!important;overflow-y:auto!important;padding:0 0 12px 0!important;background:var(--side-bg)!important;border-bottom:none!important;border-right:1px solid var(--gold)!important;z-index:200!important}
#hdr-brand{padding:16px 16px 12px 16px!important;flex-direction:row!important;align-items:center!important;gap:10px!important}
#hdr-rule{display:none!important}
#hdr nav{flex-direction:column!important;gap:0!important;align-items:stretch!important;width:100%}
#hdr .nav-btn{width:100%!important;justify-content:flex-start!important;text-align:left!important;border-bottom:none!important;padding:9px 16px!important;font-size:13px!important;gap:8px;display:flex;align-items:center}
#hdr .nav-btn.active{border-bottom:none!important;border-left:3px solid var(--gold)!important;background:var(--side-active-bg)!important;color:var(--gold)!important;font-weight:600}
#hdr .nav-dd{flex-direction:column!important;width:100%;align-items:stretch}
#hdr .nav-dd-menu{position:static!important;box-shadow:none!important;border:none!important;background:transparent!important;min-width:0!important;padding:0 0 4px 12px!important;border-radius:0!important;top:auto;right:auto}
#hdr>div[style*="margin-left:auto"]{margin-left:0!important;margin-top:auto!important;flex-direction:column!important;align-items:stretch!important;gap:8px!important;padding:12px 12px 0 12px!important;border-top:1px solid rgba(255,255,255,.08)}
#hdr #nav-profile{width:100%}
#hdr #hdr-props{text-align:left!important}
#main-content{margin-left:216px!important}
@media print{#hdr{display:none!important}#main-content{margin-left:0!important}}
/* ===== Home (role dashboard) ===== */
.home-h{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:18px}
.home-title{font-size:22px;font-weight:600;color:var(--tx)}
.home-sub{font-size:13px;color:var(--tx2);margin-top:2px}
.home-rolepill{background:var(--side-active-bg);color:var(--gold);border:1px solid var(--gold);border-radius:20px;padding:5px 12px;font-size:12px;font-weight:600;white-space:nowrap}
.home-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;margin-bottom:22px}
.home-card{background:var(--card);border:.5px solid var(--bdr);border-radius:var(--rl);padding:15px;cursor:pointer;transition:all .12s;display:flex;gap:12px;align-items:flex-start}
.home-card:hover{border-color:var(--gold);transform:translateY(-1px)}
.home-card>i{font-size:22px;color:var(--gold);line-height:1}
.home-card .hc-t{font-weight:600;color:var(--tx);font-size:14px}
.home-card .hc-d{font-size:12px;color:var(--tx2);margin-top:3px;line-height:1.35}
.home-bucket{margin-bottom:16px}
.home-bucket h3{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--tx2);margin:0 0 8px 0;display:flex;align-items:center;gap:8px}
.home-bucket .cnt{background:var(--bg3);border:.5px solid var(--bdr);border-radius:20px;padding:1px 8px;font-size:11px;color:var(--tx2)}
.home-row{display:flex;align-items:center;gap:10px;padding:9px 12px;border:.5px solid var(--bdr);border-radius:var(--r);margin-bottom:6px;background:var(--card);cursor:pointer;transition:border-color .12s}
.home-row:hover{border-color:var(--gold)}
.home-row .dot{width:8px;height:8px;border-radius:50%;flex:0 0 auto}
.home-row .rl{flex:1;min-width:0;overflow:hidden}
.home-row .rl b{font-weight:600;color:var(--tx);font-size:13px}
.home-row .rl span{color:var(--tx2);font-size:12px;margin-left:6px}
.home-row .rt{font-size:11px;color:var(--tx3);white-space:nowrap}
.home-empty{color:var(--tx3);font-size:13px;padding:14px;border:1px dashed var(--bdr);border-radius:var(--r);text-align:center}

